import { listTools, callTool } from "./server.mjs";

(async () => {
  // default advertised in schema
  console.log("default:", (await listTools())[0].inputSchema.properties.limit.default);
  console.log("additionalProperties:", (await listTools())[0].inputSchema.additionalProperties);

  // case-insensitive match, default limit 2 (alpha, beta+gamma contain "a"? alpha has a, gamma has a => 2)
  console.log("query a:", JSON.parse((await callTool("search_records", { query: "a" })).content[0].text).records.map(r=>r.name));

  // explicit limit
  console.log("limit 3:", JSON.parse((await callTool("search_records", { query: "a", limit: 3 })).content[0].text).records.length);

  // uppercase query
  console.log("query ALPH:", JSON.parse((await callTool("search_records", { query: "ALPH" })).content[0].text).records.map(r=>r.name));

  // extra argument rejected
  try { await callTool("search_records", { query: "a", foo: 1 }); console.log("FAIL: extra not rejected"); }
  catch (e) { console.log("extra rejected:", e.code, e.message); }

  // missing query rejected
  try { await callTool("search_records", {}); console.log("FAIL: missing query not rejected"); }
  catch (e) { console.log("missing query rejected:", e.code, e.message); }

  // invalid limit (out of range)
  try { await callTool("search_records", { query: "a", limit: 5 }); console.log("FAIL: limit 5 not rejected"); }
  catch (e) { console.log("limit 5 rejected:", e.code, e.message); }

  // invalid limit type
  try { await callTool("search_records", { query: "a", limit: "x" }); console.log("FAIL: bad limit type not rejected"); }
  catch (e) { console.log("bad limit type rejected:", e.code, e.message); }

  // unknown tool rejected
  try { await callTool("bogus", {}); console.log("FAIL: unknown tool not rejected"); }
  catch (e) { console.log("unknown tool rejected:", e.code, e.message); }
})();
'"}

